from pathlib import Path
import os,signal,subprocess
repo=Path('/Users/steventran/jobpipe')
test=repo/'tests/test_application_answers.py'
expected='2b57fff8ec673fef7fbeb6fe5ce00110a48a3f34'
def git(*a):return subprocess.run(['git',*a],cwd=repo,capture_output=True,text=True,check=True).stdout.strip()
if git('rev-parse','HEAD')!=expected or git('rev-parse','origin/main')!=expected:raise SystemExit('HEAD_CHANGED')
status=git('status','--porcelain=v1','-z').split('\0')
print('DIRTY',repr([s for s in status if s]),flush=True)
allowed={'adapters/protocol.py','do-again.toml','do-again-policy.json','tests/test_application_answers.py'}
if any(s[3:] not in allowed for s in status if s):raise SystemExit('UNEXPECTED_DIRTY')
original=subprocess.run(['git','show','HEAD:tests/test_application_answers.py'],cwd=repo,capture_output=True,text=True,check=True).stdout
current=test.read_text()
if not current.startswith(original) or current.count('def test_verified_global_answer_reused_across_distinct_job_plans_without_scope_leak(')!=1:raise SystemExit('EXISTING_ACCEPTANCE_TEST_CHANGED')
def run(paths,timeout):
 p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','--maxfail=1','--tb=short',*paths],cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=timeout)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',paths,o[-2500:],flush=True);raise SystemExit(124)
 print('RESULT',paths,p.returncode,o[-3500:],e[-400:],flush=True)
 return p.returncode
if run(['tests/test_application_answers.py','tests/test_application_answer_resolution.py'],160):raise SystemExit('ANSWER_REGRESSION_FAILURE')
subprocess.run(['git','add','--','tests/test_application_answers.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','test: verify cross-job answer reuse with scoped exclusion'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD'),flush=True)
